-- Catalog columns only; no hosted records. Fixture for private record RPCs.
create table public.payments("id" uuid default uuid_generate_v4() primary key,
"player_id" bigint,
"event_id" bigint,
"amount" numeric(10,2),
"currency" text default 'ZAR'::text,
"status" text default 'pending'::text,
"payment_type" text,
"payment_method" text default 'paystack'::text,
"reference" text,
"metadata" jsonb default '{}'::jsonb,
"created_at" timestamp with time zone default timezone('utc'::text, now()),
"is_test" boolean default false);
create table public.event_registrations("id" uuid default uuid_generate_v4() primary key,
"created_at" timestamp with time zone default timezone('utc'::text, now()),
"event_id" bigint,
"full_name" text,
"email" text,
"phone" text,
"partner_name" text,
"division" text,
"payment_status" text default 'pending'::text,
"is_test" boolean default false,
"payment_method" text,
"division_id" uuid,
"partner_email" text,
"partner_payment_status" text default 'pending'::text,
"status" text default 'registered'::text,
"registered_by" text,
"withdrawn_at" timestamp with time zone,
"pay_token" uuid default uuid_generate_v4(),
"reminder_sent_at" timestamp with time zone,
"close_reminder_sent_at" timestamp with time zone,
"refunded_at" timestamp with time zone,
"refund_amount" numeric(10,2),
"whatsapp_added" boolean default false,
"tshirt_size" text,
"tshirt_sponsor_name" text,
"tshirt_logo_url" text,
"reminder_7d_sent_at" timestamp with time zone,
"reminder_3d_sent_at" timestamp with time zone,
"reminder_1d_sent_at" timestamp with time zone,
"access_grant_id" uuid);
alter table public.event_registrations add unique(event_id,email,division);
alter table public.payments add unique(reference);
alter table public.event_registrations enable row level security;
alter table public.payments enable row level security;
